import{describe,it,expect}from"vitest";import{folkTalesData,filterTales,groupTalesByState,groupTalesByRegion,groupTalesByCategory,getUniqueStates,getUniqueCategories,getUniqueRegions}from"../../frontend/folk-tales/folk-tales.js";const REQUIRED_FIELDS=["id","title","state","stateCode","region","category","moral","summary","fullStory","image","tags"];describe("Indian Folk Tales Data Integrity",()=>{it("contains at least 30 folk tales in the dataset",()=>{expect(folkTalesData.length).toBeGreaterThanOrEqual(30)}),it("every story contains all required fields with non-empty values",()=>{folkTalesData.forEach((e,t)=>{REQUIRED_FIELDS.forEach(a=>{expect(e,`Story at index ${t} missing field ${a}`).toHaveProperty(a),"tags"===a?(expect(Array.isArray(e.tags)).toBe(!0),expect(e.tags.length).toBeGreaterThan(0)):(expect(typeof e[a]).toBe("string"),expect(e[a].trim().length).toBeGreaterThan(0))})})}),it("all story IDs are unique",()=>{const e=folkTalesData.map(e=>e.id),t=new Set(e);expect(t.size).toBe(e.length)}),it("all story titles are unique",()=>{const e=folkTalesData.map(e=>e.title),t=new Set(e);expect(t.size).toBe(e.length)}),it("covers multiple geographic regions of India",()=>{const e=new Set(folkTalesData.map(e=>e.region));expect(e.has("North")).toBe(!0),expect(e.has("South")).toBe(!0),expect(e.has("East")).toBe(!0),expect(e.has("West")).toBe(!0),expect(e.has("Central")).toBe(!0),expect(e.has("Northeast")).toBe(!0)}),it("covers at least 15 distinct Indian states",()=>{const e=new Set(folkTalesData.map(e=>e.state));expect(e.size).toBeGreaterThanOrEqual(15)})}),describe("Folk Tales Filtering & Search Algorithms",()=>{it("returns all tales when search query and filters are default",()=>{const e=filterTales(folkTalesData);expect(e.length).toBe(folkTalesData.length)}),it("filters tales by title query",()=>{const e=filterTales(folkTalesData,{search:"Birbal"});expect(e.length).toBeGreaterThan(0),e.forEach(e=>{const t=e.title.toLowerCase().includes("birbal")||e.summary.toLowerCase().includes("birbal")||e.tags.includes("birbal");expect(t).toBe(!0)})}),it("filters tales by state code or name",()=>{const e=filterTales(folkTalesData,{state:"wb"});expect(e.length).toBeGreaterThan(0),e.forEach(e=>{expect(e.stateCode).toBe("wb")})}),it("filters tales by region",()=>{const e=filterTales(folkTalesData,{region:"south"});expect(e.length).toBeGreaterThan(0),e.forEach(e=>{expect(e.region.toLowerCase()).toBe("south")})}),it("filters tales by category",()=>{const e=filterTales(folkTalesData,{category:"royal trickster"});expect(e.length).toBeGreaterThan(0),e.forEach(e=>{expect(e.category.toLowerCase()).toBe("royal trickster")})}),it("combines search query, state, and region filters correctly",()=>{const e=filterTales(folkTalesData,{search:"jackal",region:"south"});expect(e.length).toBeGreaterThan(0),e.forEach(e=>{expect(e.region.toLowerCase()).toBe("south")})}),it("returns empty array when search query matches no story",()=>{const e=filterTales(folkTalesData,{search:"nonexistentstoryquery12345"});expect(e.length).toBe(0)}),it("handles invalid or empty inputs gracefully",()=>{expect(filterTales(null)).toEqual([]),expect(filterTales(void 0)).toEqual([]),expect(filterTales([])).toEqual([])})}),describe("Folk Tales Grouping Logic",()=>{it("groups tales accurately by state",()=>{const e=groupTalesByState(folkTalesData);expect(Object.keys(e).length).toBeGreaterThanOrEqual(15),expect(e["Uttar Pradesh"]).toBeDefined(),expect(e["Uttar Pradesh"].some(e=>"birbal-khichdi"===e.id)).toBe(!0)}),it("groups tales accurately by region",()=>{const e=groupTalesByRegion(folkTalesData);expect(e.North).toBeDefined(),expect(e.South).toBeDefined(),expect(e.East).toBeDefined(),expect(e.West).toBeDefined(),expect(e.Central).toBeDefined(),expect(e.Northeast).toBeDefined()}),it("groups tales accurately by category",()=>{const e=groupTalesByCategory(folkTalesData);expect(e["Royal Trickster"]).toBeDefined(),expect(e["Myth & Legend"]).toBeDefined(),expect(e["Animal Fable"]).toBeDefined()}),it("handles invalid input for grouping functions",()=>{expect(groupTalesByState(null)).toEqual({}),expect(groupTalesByRegion(void 0)).toEqual({}),expect(groupTalesByCategory(123)).toEqual({})})}),describe("Folk Tales Utility Functions",()=>{it("extracts unique states sorted alphabetically by name",()=>{const e=getUniqueStates(folkTalesData);expect(e.length).toBeGreaterThanOrEqual(15),expect(e[0]).toHaveProperty("code"),expect(e[0]).toHaveProperty("name");for(let t=1;t<e.length;t++)expect(e[t-1].name.localeCompare(e[t].name)).toBeLessThanOrEqual(0)}),it("extracts unique categories sorted alphabetically",()=>{const e=getUniqueCategories(folkTalesData);expect(e.length).toBeGreaterThan(0),expect(e).toContain("Royal Trickster"),expect(e).toContain("Animal Fable")}),it("extracts unique regions",()=>{const e=getUniqueRegions(folkTalesData);expect(e).toContain("North"),expect(e).toContain("South"),expect(e).toContain("East")})});